/**
 * extract-sessions.js
 * Run once from the angular-app folder:
 *   node extract-sessions.js
 *
 * Scans every session-* component folder, extracts bilingual content
 * and SEO metadata, and writes src/app/session-detail/sessions-data.ts.
 */

const fs   = require('fs');
const path = require('path');

const APP_DIR  = path.join(__dirname, 'src', 'app');
const OUT_FILE = path.join(APP_DIR, 'session-detail', 'sessions-data.ts');

// ── helpers ──────────────────────────────────────────────────────────────────

/** Extract the inner HTML of the first <div class="session-report" dir="..."> */
function extractSessionReport(html, dir) {
    const openTag = `<div class="session-report" dir="${dir}">`;
    const start   = html.indexOf(openTag);
    if (start === -1) return '';

    let depth     = 1;
    let i         = start + openTag.length;
    const content = [];

    while (i < html.length && depth > 0) {
        if (html.startsWith('<div', i)) depth++;
        if (html.startsWith('</div>', i)) {
            depth--;
            if (depth === 0) break;
        }
        content.push(html[i]);
        i++;
    }
    return content.join('').trim();
}

/** Extract a string literal after a given key pattern in TypeScript source */
function extractTsSingleQuote(ts, keyPattern) {
    const re  = new RegExp(keyPattern + "\\s*:\\s*isFr\\s*\\?\\s*'([^']*)'\\s*:\\s*'([^']*)'");
    const m   = ts.match(re);
    return m ? { fr: m[1], ar: m[2] } : { fr: '', ar: '' };
}

/** Extract page-header h1 titles */
function extractTitles(html) {
    const frM = html.match(/<h1[^>]*currentLang\(\)\s*===\s*'fr'[^>]*>([^<]+)<\/h1>/);
    const arM = html.match(/<h1[^>]*currentLang\(\)\s*===\s*'ar'[^>]*>([^<]+)<\/h1>/);
    return {
        fr: frM ? frM[1].trim() : '',
        ar: arM ? arM[1].trim() : ''
    };
}

/** Escape backticks for embedding in template literals */
function esc(s) {
    return s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
}

// ── main ─────────────────────────────────────────────────────────────────────

const dirs = fs.readdirSync(APP_DIR)
    .filter(d => d.startsWith('session-') && d !== 'session-detail' && fs.statSync(path.join(APP_DIR, d)).isDirectory());

const sessions = [];

for (const dir of dirs) {
    const dirPath = path.join(APP_DIR, dir);
    const files   = fs.readdirSync(dirPath);

    const htmlFile = files.find(f => f.endsWith('.html'));
    const tsFile   = files.find(f => f.endsWith('.ts') && !f.endsWith('.spec.ts'));

    if (!htmlFile || !tsFile) {
        console.warn(`  ⚠  Skipping ${dir} (missing html or ts file)`);
        continue;
    }

    const html = fs.readFileSync(path.join(dirPath, htmlFile), 'utf8');
    const ts   = fs.readFileSync(path.join(dirPath, tsFile),   'utf8');

    const titles      = extractTitles(html);
    const seoTitle    = extractTsSingleQuote(ts, 'title');
    const seoDesc     = extractTsSingleQuote(ts, 'description');
    const seoKeywords = extractTsSingleQuote(ts, 'keywords');

    const imageM = ts.match(/image:\s*'([^']+)'/);
    const image  = imageM ? imageM[1] : 'assets/images/session-unified.jpg';

    const contentFr = extractSessionReport(html, 'ltr');
    const contentAr = extractSessionReport(html, 'rtl');

    sessions.push({ slug: dir, titles, seoTitle, seoDesc, seoKeywords, image, contentFr, contentAr });
    console.log(`  ✓  ${dir}`);
}

// ── generate output ───────────────────────────────────────────────────────────

const entries = sessions.map(s => `    {
        slug: '${s.slug}',
        titleFr: \`${esc(s.titles.fr)}\`,
        titleAr: \`${esc(s.titles.ar)}\`,
        image: '${s.image}',
        seo: {
            titleFr:       \`${esc(s.seoTitle.fr)}\`,
            titleAr:       \`${esc(s.seoTitle.ar)}\`,
            descriptionFr: \`${esc(s.seoDesc.fr)}\`,
            descriptionAr: \`${esc(s.seoDesc.ar)}\`,
            keywordsFr:    \`${esc(s.seoKeywords.fr)}\`,
            keywordsAr:    \`${esc(s.seoKeywords.ar)}\`
        },
        contentFr: \`${esc(s.contentFr)}\`,
        contentAr: \`${esc(s.contentAr)}\`
    }`).join(',\n');

const output = `// AUTO-GENERATED by extract-sessions.js — do not edit by hand.
// To regenerate: node angular-app/extract-sessions.js

export interface SessionData {
    slug:    string;
    titleFr: string;
    titleAr: string;
    image:   string;
    seo: {
        titleFr:       string;
        titleAr:       string;
        descriptionFr: string;
        descriptionAr: string;
        keywordsFr:    string;
        keywordsAr:    string;
    };
    contentFr: string;
    contentAr: string;
}

export const SESSION_DATA: SessionData[] = [
${entries}
];

/** Look up a session by its URL slug (with or without .html suffix). */
export function findSession(slug: string): SessionData | undefined {
    const clean = slug.replace(/\\.html$/, '');
    return SESSION_DATA.find(s => s.slug === clean);
}
`;

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, output, 'utf8');
console.log(`\n✅  Written ${sessions.length} sessions → ${OUT_FILE}`);
